// scanTaskBadges scans rows into TaskBadge entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanTaskBadges(rows database.Rows, columns []string) ([]*TaskBadge, error) {
	var result []*TaskBadge
	for rows.Next() {
		t := &TaskBadge{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "task_id":
				targets[idx] = &t.TaskID
			case "badge_code":
				targets[idx] = &t.BadgeCode
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan task_badge: %w", err)
		}

		result = append(result, t)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate task_badge rows: %w", err)
	}
	return result, nil
}

