// Paginate returns a page of task_badges with total count for offset-based pagination.
// A nil filter paginates all task_badges.
func (c *taskBadgeClient) Paginate(ctx context.Context, input PaginateInput[TaskBadgeFilter], opts ...func(*CallOptions[TaskBadgeFieldOptions])) (*PaginateResult[TaskBadge], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("paginate task_badges: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableTaskBadges, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[TaskBadgeFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		taskBadges, err := c.GetMany(ctx, &GetTaskBadgesInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		return &PaginateResult[TaskBadge]{
			Items:      taskBadges,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    input.Limit > 0 && int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("paginate task_badges: %w", err)
	}
	return result.(*PaginateResult[TaskBadge]), nil
}

// Connection returns a Relay-style cursor-paginated connection of task_badges.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *taskBadgeClient) Connection(ctx context.Context, input ConnectionInput[TaskBadgeFilter], opts ...func(*CallOptions[TaskBadgeFieldOptions])) (*Connection[TaskBadge], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection task_badges: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableTaskBadges, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[TaskBadgeFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeTaskBadgeCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeTaskBadgeCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		taskBadges, err := c.GetMany(ctx, &GetTaskBadgesInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(taskBadges) > limit
		if hasMore {
			taskBadges = taskBadges[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(taskBadges)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[TaskBadge], len(taskBadges))
		for i, row := range taskBadges {
			cursor, err := encodeTaskBadgeCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[TaskBadge]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[TaskBadge]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection task_badges: %w", err)
	}
	return result.(*Connection[TaskBadge]), nil
}

// encodeTaskBadgeCursor encodes cursor key values as a base64 JSON string.
func encodeTaskBadgeCursor(keys []string, t *TaskBadge) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "task_id":
			out["task_id"] = t.TaskID
		case "badge_code":
			out["badge_code"] = t.BadgeCode
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode task_badge cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeTaskBadgeCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeTaskBadgeCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row TaskBadge
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "task_id":
			err = json.Unmarshal(raw[key], &row.TaskID)
			out[key] = row.TaskID
		case "badge_code":
			err = json.Unmarshal(raw[key], &row.BadgeCode)
			out[key] = row.BadgeCode
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

