// Paginate returns a page of template_labels with total count for offset-based pagination.
// A nil filter paginates all template_labels.
func (c *templateLabelClient) Paginate(ctx context.Context, input PaginateInput[TemplateLabelFilter], opts ...func(*CallOptions[TemplateLabelFieldOptions])) (*PaginateResult[TemplateLabel], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("paginate template_labels: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableTemplateLabels, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[TemplateLabelFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		templateLabels, err := c.GetMany(ctx, &GetTemplateLabelsInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		return &PaginateResult[TemplateLabel]{
			Items:      templateLabels,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    input.Limit > 0 && int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("paginate template_labels: %w", err)
	}
	return result.(*PaginateResult[TemplateLabel]), nil
}

// Connection returns a Relay-style cursor-paginated connection of template_labels.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *templateLabelClient) Connection(ctx context.Context, input ConnectionInput[TemplateLabelFilter], opts ...func(*CallOptions[TemplateLabelFieldOptions])) (*Connection[TemplateLabel], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection template_labels: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableTemplateLabels, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[TemplateLabelFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeTemplateLabelCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeTemplateLabelCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		templateLabels, err := c.GetMany(ctx, &GetTemplateLabelsInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(templateLabels) > limit
		if hasMore {
			templateLabels = templateLabels[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(templateLabels)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[TemplateLabel], len(templateLabels))
		for i, row := range templateLabels {
			cursor, err := encodeTemplateLabelCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[TemplateLabel]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[TemplateLabel]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection template_labels: %w", err)
	}
	return result.(*Connection[TemplateLabel]), nil
}

// encodeTemplateLabelCursor encodes cursor key values as a base64 JSON string.
func encodeTemplateLabelCursor(keys []string, t *TemplateLabel) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "workspace_id":
			out["workspace_id"] = t.WorkspaceID
		case "template_id":
			out["template_id"] = t.TemplateID
		case "label_id":
			out["label_id"] = t.LabelID
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode template_label cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeTemplateLabelCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeTemplateLabelCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row TemplateLabel
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "workspace_id":
			err = json.Unmarshal(raw[key], &row.WorkspaceID)
			out[key] = row.WorkspaceID
		case "template_id":
			err = json.Unmarshal(raw[key], &row.TemplateID)
			out[key] = row.TemplateID
		case "label_id":
			err = json.Unmarshal(raw[key], &row.LabelID)
			out[key] = row.LabelID
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

